def passed(text):report['checks'].append(text);print('PASS',text,flush=True)
def click(p,a):p.locator('[data-learn="'+a+'"]').filter(visible=True).first.click()
def snap(p):return p.evaluate('window.aquariumLearningSnapshot()')
def prepare(p,grade,mission=None):technical_start(p,grade,mission)
def plan(p):
 for key,text in {'question':'Welche Änderung beeinflusst den Verlauf?','hypothesis':'Ich vermute einen Unterschied durch den Eingriff.','prediction':'Der Eingriff verändert den Verlauf gegenüber der Kontrolle.','plan':'Gleicher Anfang, eine Änderung, beide Seiten messen.'}.items():
  loc=p.locator(f'[data-learning-note="{key}"]')
  if loc.count():loc.first.fill(text)
def shot(p,name):p.screenshot(path=str(OUT/name));report['screenshots'].append(name)
def download(p,action,name):
 with p.expect_download() as d:click(p,action)
 file=OUT/name;d.value.save_as(str(file));return file
def context(browser,touch=False):
 c=browser.new_context(viewport={'width':768 if touch else 1360,'height':1024 if touch else 960},is_mobile=touch,has_touch=touch,accept_downloads=True)
 c.add_init_script("if(!localStorage.getItem('aquarium-graphics-v1'))localStorage.setItem('aquarium-graphics-v1',JSON.stringify({version:1,profile:'ipad'}))")
 p=c.new_page();p.set_default_timeout(90000);p.on('pageerror',lambda e:report['errors'].append(str(e)));p.on('requestfailed',lambda r:report['failed_requests'].append(r.url));p.goto(URL);p.wait_for_function('!!window.aquariumLearningSnapshot');return c,p
def records(path):return list(csv.DictReader(io.StringIO(path.read_text()),delimiter=';'))
def retained(expected,actual):
 # The legacy reader can add empty optional fields; every original value stays exact.
 if isinstance(expected,dict):
  for key,value in expected.items():assert key in actual,key;retained(value,actual[key])
 elif isinstance(expected,list):
  assert len(expected)==len(actual)
  for before,after in zip(expected,actual):retained(before,after)
 else:assert actual==expected,(actual,expected)

